1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Calendar, Check } from 'lucide-react-native';
3	import { nanoid } from 'nanoid/non-secure';
4	import React, { useEffect, useMemo, useState } from 'react';
5	import {
6	  ActivityIndicator,
7	  KeyboardAvoidingView,
8	  Platform,
9	  Pressable,
10	  ScrollView,
11	  StyleSheet,
12	  View,
13	} from 'react-native';
14	import {
15	  AppBar,
16	  Button,
17	  Card,
18	  QtyStepper,
19	  radius,
20	  spacing,
21	  Text,
22	} from '../../../design';
23	import { getSession } from '../../../auth/session';
24	import { correctStockLocal, findStock, getNearestExpiry, StockRow } from '../../../db/stock';
25	import { enqueue } from '../../../db/outbox';
26	import { useT } from '../../../i18n';
27	import { useTheme } from '../../../theme';
28	import { RootStackParamList } from '../../../navigation/types';
29	import { api, ApiError } from '../../../sync/api';
30	import { flushOnce } from '../../../sync/syncService';
31	import { haptic } from '../../../utils/haptics';
32	import { DatePickerModal } from '../components/DatePickerModal';
33	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
34	
35	type Props = NativeStackScreenProps<RootStackParamList, 'EditStock'>;
36	
37	function formatForDisplay(iso: string): string {
38	  try {
39	    const [y, m, d] = iso.split('-');
40	    return `${d}/${m}/${y}`;
41	  } catch {
42	    return iso;
43	  }
44	}
45	
46	function toISO(d: Date): string {
47	  return d.toISOString().split('T')[0];
48	}
49	
50	/** Earliest date out of a list; nulls ignored. Returns null if all null. */
51	function earliestISO(dates: (Date | null)[]): string | null {
52	  const isos = dates.filter((d): d is Date => !!d).map(toISO).sort();
53	  return isos[0] ?? null;
54	}
55	
56	/**
57	 * verifying  — JIT fetch in flight; save disabled.
58	 * ok         — server agrees with what we opened the screen with.
59	 * absent     — server has no row for this barcode (treat as ok — local
60	 *              view is the only truth; the correction will create it).
61	 * conflict   — server's on_hand or nearest_expiry differs from local;
62	 *              show prompt before letting user save.
63	 * offline    — fetch failed because network down; save disabled.
64	 * error      — fetch failed otherwise; save disabled.
65	 */
66	type VerifyStatus = 'verifying' | 'ok' | 'absent' | 'conflict' | 'offline' | 'error';
67	
68	function isOfflineError(err: unknown): boolean {
69	  const msg = err instanceof Error ? err.message : String(err);
70	  return (
71	    msg.includes('Network request failed') ||
72	    msg.includes('TypeError: Network') ||
73	    msg.includes('Unable to resolve host') ||
74	    msg === 'JIT timeout'
75	  );
76	}
77	
78	export function EditStockScreen({ route, navigation }: Props) {
79	  const t = useT();
80	  const { palette } = useTheme();
81	  const kbHeight = useKeyboardHeight();
82	  const { barcode } = route.params;
83	
84	  const [row, setRow] = useState<StockRow | null>(null);
85	  const [originalQty, setOriginalQty] = useState<number>(0);
86	  const [originalExpiry, setOriginalExpiry] = useState<string | null>(null);
87	  const [qty, setQty] = useState<number>(0);
88	  const [expiryDateObj, setExpiryDateObj] = useState<Date | null>(null);
89	  const [noExpiry, setNoExpiry] = useState<boolean>(false);
90	
91	  // Per-pack expiry. Mirrors ReceivingScreen: off by default; appears only
92	  // when qty > 1 and not noExpiry. When on, expand into N rows so the
93	  // guard can set a different expiry on each pack.
94	  const [perPackExpiry, setPerPackExpiry] = useState(false);
95	  const [perPackExpiries, setPerPackExpiries] = useState<(Date | null)[]>([]);
96	  const [editingPackIdx, setEditingPackIdx] = useState<number | null>(null);
97	
98	  const [showPicker, setShowPicker] = useState(false);
99	  const [saving, setSaving] = useState(false);
100	
101	  // JIT verification — fetch the server's authoritative on_hand +
102	  // nearest_expiry the moment the screen opens, in parallel with the
103	  // local read. If the server differs, we surface a "Stock has changed"
104	  // prompt before letting the user save. If the fetch fails (timeout /
105	  // offline / 5xx), we block the save entirely — corrections must be
106	  // committed against verified state per the cache-freshness plan.
107	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('verifying');
108	  const [serverQty, setServerQty] = useState<number | null>(null);
109	  const [serverExpiry, setServerExpiry] = useState<string | null>(null);
110	
111	  useEffect(() => {
112	    let cancelled = false;
113	    (async () => {
114	      const r = await findStock(barcode);
115	      const exp = await getNearestExpiry(barcode);
116	      if (cancelled) return;
117	      if (!r) return;
118	      setRow(r);
119	      setOriginalQty(r.on_hand);
120	      setOriginalExpiry(exp);
121	      setQty(r.on_hand);
122	      if (exp) {
123	        setExpiryDateObj(new Date(exp));
124	        setNoExpiry(false);
125	      } else {
126	        setNoExpiry(true);
127	      }
128	    })();
129	    return () => { cancelled = true; };
130	  }, [barcode]);
131	
132	  // Fire the JIT fetch independently of the local read so neither
133	  // blocks the other. The 3 s timeout matches CatalogPickerScreen.
134	  useEffect(() => {
135	    let cancelled = false;
136	    const controller = new AbortController();
137	    const t = setTimeout(() => controller.abort(), 3000);
138	    (async () => {
139	      try {
140	        const remote = await api.fetch.stockOne(barcode);
141	        if (cancelled) return;
142	        const remoteQty = Number(remote.on_hand);
143	        const remoteExpiry = remote.nearest_expiry ?? null;
144	        setServerQty(remoteQty);
145	        setServerExpiry(remoteExpiry);
146	        setVerifyStatus('ok'); // narrowed to 'conflict' below once we know local values
147	      } catch (err) {
148	        if (cancelled) return;
149	        // 404 = no stock row on server; treat as authoritative "absent"
150	        // — the correction will create it. Same UX as a clean ok.
151	        if (err instanceof ApiError && err.status === 404) {
152	          setVerifyStatus('absent');
153	          return;
154	        }
155	        // 401 is handled centrally; clear navigates to Login.
156	        if (err instanceof ApiError && err.status === 401) return;
157	        setVerifyStatus(isOfflineError(err) ? 'offline' : 'error');
158	      } finally {
159	        clearTimeout(t);
160	      }
161	    })();
162	    return () => { cancelled = true; clearTimeout(t); controller.abort(); };
163	  }, [barcode]);
164	
165	  // Once both local and server have settled, classify ok-vs-conflict.
166	  // Conflict iff server differs from what the user is about to edit.
167	  // We use originalQty/originalExpiry as the "what the user opened
168	  // with" reference — those don't change unless the user explicitly
169	  // accepts the new server values.
170	  useEffect(() => {
171	    if (verifyStatus !== 'ok' || row === null || serverQty === null) return;
172	    const qtyDiffers = Math.abs(serverQty - originalQty) > 1e-9;
173	    const expiryDiffers = (serverExpiry ?? null) !== (originalExpiry ?? null);
174	    if (qtyDiffers || expiryDiffers) setVerifyStatus('conflict');
175	  }, [verifyStatus, row, serverQty, serverExpiry, originalQty, originalExpiry]);
176	
177	  // Keep the per-pack list in sync with qty when toggle is on. Seed new
178	  // rows with the bulk expiry so the guard only edits the differing ones.
179	  useEffect(() => {
180	    if (!perPackExpiry) return;
181	    setPerPackExpiries((prev) => {
182	      const n = Math.max(1, Math.floor(qty));
183	      if (prev.length === n) return prev;
184	      const next = [...prev];
185	      while (next.length < n) next.push(expiryDateObj);
186	      while (next.length > n) next.pop();
187	      return next;
188	    });
189	  }, [perPackExpiry, qty, expiryDateObj]);
190	
191	  // Auto-disable per-pack when the toggle's preconditions go away
192	  // (qty drops to 1, or guard checks "no expiry").
193	  useEffect(() => {
194	    if (perPackExpiry && (qty <= 1 || noExpiry)) {
195	      setPerPackExpiry(false);
196	    }
197	  }, [perPackExpiry, qty, noExpiry]);
198	
199	  /** Single new_expiry sent to server when per-pack is off. */
200	  const newSingleExpiry = useMemo(() => {
201	    if (noExpiry || perPackExpiry || !expiryDateObj) return null;
202	    return toISO(expiryDateObj);
203	  }, [expiryDateObj, noExpiry, perPackExpiry]);
204	
205	  /** Array of expiries sent when per-pack is on. */
206	  const newExpiriesArray = useMemo<string[] | null>(() => {
207	    if (noExpiry || !perPackExpiry) return null;
208	    return perPackExpiries.map((d) => (d ? toISO(d) : '')).filter((s) => s.length > 0);
209	  }, [noExpiry, perPackExpiry, perPackExpiries]);
210	
211	  /** Whatever ends up as the locally-tracked "nearest" expiry. */
212	  const localNearestExpiry = useMemo(() => {
213	    if (noExpiry) return null;
214	    if (perPackExpiry) return earliestISO(perPackExpiries);
215	    return expiryDateObj ? toISO(expiryDateObj) : null;
216	  }, [noExpiry, perPackExpiry, perPackExpiries, expiryDateObj]);
217	
218	  const changed = useMemo(() => {
219	    if (!row) return false;
220	    if (qty !== originalQty) return true;
221	    if (localNearestExpiry !== originalExpiry) return true;
222	    // Per-pack with same nearest as original still counts as a change if
223	    // any pack carries a date different from the bulk default.
224	    if (perPackExpiry) return true;
225	    return false;
226	  }, [row, qty, originalQty, localNearestExpiry, originalExpiry, perPackExpiry]);
227	
228	  const packDisplay = row && row.pack_size != null && row.pack_size !== 1 && row.unit
229	    ? `${row.pack_size} ${row.unit}`
230	    : row?.unit ?? null;
231	
232	  /**
233	   * User accepted the server's view. Rebase originalQty / originalExpiry
234	   * and also replace what's in the steppers / date picker so the
235	   * "current count" line and the inputs match. The audit record's
236	   * old_qty / old_expiry will now reflect the actual transition.
237	   */
238	  const acceptServerView = () => {
239	    if (serverQty === null) return;
240	    haptic.tap();
241	    setOriginalQty(serverQty);
242	    setQty(serverQty);
243	    setOriginalExpiry(serverExpiry ?? null);
244	    if (serverExpiry) {
245	      setExpiryDateObj(new Date(serverExpiry));
246	      setNoExpiry(false);
247	    } else {
248	      setExpiryDateObj(null);
249	      setNoExpiry(true);
250	    }
251	    setPerPackExpiry(false);
252	    setPerPackExpiries([]);
253	    setVerifyStatus('ok');
254	  };
255	
256	  /**
257	   * User chose to keep their edit. We still rebase originalQty /
258	   * originalExpiry to the SERVER's truth so the audit record reflects
259	   * "server was N, guard set it to M" — not "guard thought it was N
260	   * (stale), set it to M". Steppers untouched.
261	   */
262	  const keepUserEdit = () => {
263	    if (serverQty === null) return;
264	    haptic.tap();
265	    setOriginalQty(serverQty);
266	    setOriginalExpiry(serverExpiry ?? null);
267	    setVerifyStatus('ok');
268	  };
269	
270	  const submit = async () => {
271	    if (!row || !changed) return;
272	    const session = getSession();
273	    setSaving(true);
274	    try {
275	      await correctStockLocal(barcode, qty, localNearestExpiry);
276	      await enqueue('stock_correction', {
277	        id: `crn_${nanoid(12)}`,
278	        barcode,
279	        product_name: row.name,
280	        old_qty: originalQty,
281	        new_qty: qty,
282	        old_expiry: originalExpiry,
283	        new_expiry: newSingleExpiry,
284	        new_expiries: newExpiriesArray,
285	        performed_by: session?.guardId ?? null,
286	        performed_by_name: session?.guardName ?? null,
287	        corrected_at: Date.now(),
288	      });
289	      flushOnce().catch(() => {});
290	      haptic.success();
291	      navigation.goBack();
292	    } finally {
293	      setSaving(false);
294	    }
295	  };
296	
297	  if (!row) {
298	    return (
299	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
300	        <AppBar title={t('editStock')} onBack={() => navigation.goBack()} />
301	      </View>
302	    );
303	  }
304	
305	  return (
306	    <KeyboardAvoidingView
307	      behavior={Platform.OS === 'ios' ? 'height' : undefined}
308	      style={{ flex: 1 }}
309	    >
310	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
311	        <AppBar title={t('editStock')} subtitle={t('editStockSub')} onBack={() => navigation.goBack()} />
312	
313	        <ScrollView
314	          contentContainerStyle={[styles.content, { paddingBottom: spacing.xxxl + kbHeight }]}
315	          keyboardShouldPersistTaps="handled"
316	        >
317	          {/* JIT verification status banners.
318	              - verifying: tiny inline indicator at top
319	              - conflict: amber banner with "Use new count" / "Keep my edit"
320	              - offline/error: red banner, save disabled, can retry */}
321	          {verifyStatus === 'verifying' && (
322	            <View style={[styles.statusBanner, { borderColor: palette.outlineVariant }]}>
323	              <ActivityIndicator color={palette.primary} size="small" />
324	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginLeft: spacing.sm }}>
325	                {t('verifying')}
326	              </Text>
327	            </View>
328	          )}
329	          {verifyStatus === 'conflict' && serverQty !== null && (
330	            <View
331	              style={[
332	                styles.statusBanner,
333	                {
334	                  borderColor: '#F9A825',
335	                  backgroundColor: 'rgba(249, 168, 37, 0.10)',
336	                  flexDirection: 'column',
337	                  alignItems: 'stretch',
338	                  gap: spacing.sm,
339	                },
340	              ]}
341	            >
342	              <Text variant="titleMedium" color={palette.onSurface}>
343	                {t('stockUpdatedTitle')}
344	              </Text>
345	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
346	                {t('stockUpdatedBody')}
347	              </Text>
348	              <Text variant="bodyMedium" color={palette.onSurface}>
349	                {originalQty} → {serverQty}
350	                {row.unit ? ` ${row.unit}` : ''}
351	                {serverExpiry && serverExpiry !== originalExpiry
352	                  ? ` · ${formatForDisplay(serverExpiry)}`
353	                  : ''}
354	              </Text>
355	              <View style={{ flexDirection: 'row', gap: spacing.sm }}>
356	                <Button label={t('useNewCount')} variant="filled" size="md" onPress={acceptServerView} />
357	                <Button label={t('keepMyEdit')} variant="tonal" size="md" onPress={keepUserEdit} />
358	              </View>
359	            </View>
360	          )}
361	          {(verifyStatus === 'offline' || verifyStatus === 'error') && (
362	            <View
363	              style={[
364	                styles.statusBanner,
365	                { borderColor: palette.error, backgroundColor: palette.errorContainer ?? 'transparent' },
366	              ]}
367	            >
368	              <Text variant="bodyMedium" color={palette.error} style={{ flex: 1 }}>
369	                {t('couldntVerify')}
370	              </Text>
371	            </View>
372	          )}
373	
374	          <Card tone="elevated" padding="xl">
375	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
376	              {t('product').toUpperCase()}
377	            </Text>
378	            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: spacing.xs, gap: spacing.md }}>
379	              <Text variant="headlineSmall" style={{ flex: 1 }}>{row.name}</Text>
380	              {packDisplay ? (
381	                <Text variant="titleMedium" color={palette.onSurfaceVariant}>{packDisplay}</Text>
382	              ) : null}
383	            </View>
384	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.md }}>
385	              {t('currentCount')}: {originalQty}{row.unit ? ` ${row.unit}` : ''}
386	            </Text>
387	          </Card>
388	
389	          <View style={styles.qtySection}>
390	            <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
391	              {t('newCount').toUpperCase()}
392	            </Text>
393	            <QtyStepper value={qty} onChange={setQty} min={0} />
394	          </View>
395	
396	          <View style={styles.expirySection}>
397	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
398	              {t('expiryDate').toUpperCase()}
399	            </Text>
400	
401	            {/* Per-pack toggle. Mirrors ReceivingScreen: only useful for
402	                multi-qty edits. */}
403	            {qty > 1 && !noExpiry && (
404	              <Pressable
405	                onPress={() => { setPerPackExpiry((v) => !v); haptic.tap(); }}
406	                style={[styles.noExpiryRow, { marginTop: spacing.sm }]}
407	              >
408	                <View
409	                  style={[
410	                    styles.checkbox,
411	                    {
412	                      backgroundColor: perPackExpiry ? palette.primary : 'transparent',
413	                      borderColor: perPackExpiry ? palette.primary : palette.outline,
414	                    },
415	                  ]}
416	                >
417	                  {perPackExpiry && <Check size={14} color={palette.onPrimary} strokeWidth={3} />}
418	                </View>
419	                <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
420	                  {t('perPackExpiry')} ({Math.floor(qty)} {t('packsLabel')})
421	                </Text>
422	              </Pressable>
423	            )}
424	
425	            {!noExpiry && !perPackExpiry && (
426	              <>
427	                <Pressable
428	                  onPress={() => setShowPicker(true)}
429	                  style={[
430	                    styles.expiryInput,
431	                    {
432	                      backgroundColor: palette.surfaceContainerLowest,
433	                      borderColor: palette.outlineVariant,
434	                      flexDirection: 'row',
435	                      alignItems: 'center',
436	                    },
437	                  ]}
438	                >
439	                  <Calendar size={20} color={palette.onSurfaceVariant} strokeWidth={2} />
440	                  <Text
441	                    variant="bodyLarge"
442	                    color={expiryDateObj ? palette.onSurface : palette.onSurfaceVariant}
443	                    style={{ marginLeft: spacing.sm, flex: 1, letterSpacing: 1 }}
444	                  >
445	                    {expiryDateObj ? formatForDisplay(toISO(expiryDateObj)) : t('tapToSelectDate')}
446	                  </Text>
447	                </Pressable>
448	                {showPicker && editingPackIdx == null && (
449	                  <DatePickerModal
450	                    visible={showPicker}
451	                    value={expiryDateObj}
452	                    onSelect={(d) => { setExpiryDateObj(d); setNoExpiry(false); }}
453	                    onDismiss={() => setShowPicker(false)}
454	                  />
455	                )}
456	              </>
457	            )}
458	
459	            {!noExpiry && perPackExpiry && (
460	              <View style={{ marginTop: spacing.sm, gap: spacing.xs }}>
461	                {perPackExpiries.map((d, i) => (
462	                  <Pressable
463	                    key={i}
464	                    onPress={() => { setEditingPackIdx(i); setShowPicker(true); }}
465	                    style={[
466	                      styles.expiryInput,
467	                      {
468	                        backgroundColor: palette.surfaceContainerLowest,
469	                        borderColor: palette.outlineVariant,
470	                        flexDirection: 'row',
471	                        alignItems: 'center',
472	                      },
473	                    ]}
474	                  >
475	                    <Text variant="labelMedium" color={palette.onSurfaceVariant} style={{ marginRight: spacing.sm, minWidth: 56 }}>
476	                      {t('pack')} {i + 1}
477	                    </Text>
478	                    <Calendar size={18} color={palette.onSurfaceVariant} strokeWidth={2} />
479	                    <Text
480	                      variant="bodyLarge"
481	                      color={d ? palette.onSurface : palette.onSurfaceVariant}
482	                      style={{ marginLeft: spacing.sm, flex: 1, letterSpacing: 1 }}
483	                    >
484	                      {d ? formatForDisplay(toISO(d)) : t('tapToSelectDate')}
485	                    </Text>
486	                  </Pressable>
487	                ))}
488	                {showPicker && editingPackIdx != null && (
489	                  <DatePickerModal
490	                    visible={showPicker}
491	                    value={perPackExpiries[editingPackIdx]}
492	                    onSelect={(date) => {
493	                      setPerPackExpiries((prev) => prev.map((p, i) => (i === editingPackIdx ? date : p)));
494	                    }}
495	                    onDismiss={() => { setShowPicker(false); setEditingPackIdx(null); }}
496	                  />
497	                )}
498	              </View>
499	            )}
500	
501	            <Pressable
502	              onPress={() => { setNoExpiry(!noExpiry); haptic.tap(); }}
503	              style={styles.noExpiryRow}
504	            >
505	              <View
506	                style={[
507	                  styles.checkbox,
508	                  {
509	                    backgroundColor: noExpiry ? palette.primary : 'transparent',
510	                    borderColor: noExpiry ? palette.primary : palette.outline,
511	                  },
512	                ]}
513	              >
514	                {noExpiry && <Check size={14} color={palette.onPrimary} strokeWidth={3} />}
515	              </View>
516	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
517	                {t('noExpiry')}
518	              </Text>
519	            </Pressable>
520	          </View>
521	        </ScrollView>
522	
523	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
524	          {/* Save is gated by verification: cannot commit a correction
525	              while we're still verifying, in conflict (user must
526	              resolve via the banner), or while verification failed
527	              (offline / error — user retries by going back and re-
528	              opening once network returns). */}
529	          <Button
530	            label={changed ? t('saveChanges') : t('noChanges')}
531	            onPress={submit}
532	            loading={saving}
533	            disabled={
534	              !changed ||
535	              verifyStatus === 'verifying' ||
536	              verifyStatus === 'conflict' ||
537	              verifyStatus === 'offline' ||
538	              verifyStatus === 'error'
539	            }
540	            size="lg"
541	            fullWidth
542	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
543	          />
544	          <Button
545	            label={t('cancel')}
546	            variant="text"
547	            onPress={() => navigation.goBack()}
548	            style={{ marginTop: spacing.sm }}
549	          />
550	        </View>
551	      </View>
552	    </KeyboardAvoidingView>
553	  );
554	}
555	
556	const styles = StyleSheet.create({
557	  safe: { flex: 1 },
558	  content: { padding: spacing.xl, gap: spacing.xl },
559	  qtySection: { gap: spacing.lg, alignItems: 'stretch' },
560	  expirySection: { gap: spacing.sm },
561	  expiryInput: {
562	    borderRadius: radius.md,
563	    borderWidth: 1.5,
564	    paddingHorizontal: spacing.lg,
565	    minHeight: 52,
566	    fontSize: 18,
567	    letterSpacing: 2,
568	  },
569	  noExpiryRow: {
570	    flexDirection: 'row',
571	    alignItems: 'center',
572	    gap: spacing.sm,
573	    paddingVertical: spacing.xs,
574	  },
575	  checkbox: {
576	    width: 22,
577	    height: 22,
578	    borderRadius: 4,
