  if (pathname === "/api/inventory/stock-snapshot" && method === "GET") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    try {
      json(res, 200, { rows: await listStockForSheet(auth.siteId) });
    } catch (err) {
      logError("[Inventory] listStockForSheet failed", err, { scope: "inventory.stock" });
      json(res, 500, {
        error: `Could not load stock snapshot: ${describeError(err)}`,
      });
    }
    return true;
  }

  if (pathname === "/api/inventory/sheet/sync" && method === "POST") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const [spreadsheetId, ownerEmail] = await Promise.all([
      getSetting(auth.siteId, SHEET_ID_KEY),
      getSetting(auth.siteId, SHEET_OWNER_KEY),
    ]);
    if (!spreadsheetId || !ownerEmail) {
      json(res, 400, { error: "No Google Sheet attached for this site" });
      return true;
    }
    const sheets = await getAdminSheetsClient(ownerEmail);
    if (!sheets) {
      json(res, 400, {
        error: `The user who attached this sheet (${ownerEmail}) needs to sign in with Google again.`,
      });
      return true;
    }
    const body = await readBodyJson(req);
    const from = asString(body.from);
    const to = asString(body.to);
    const rows = await listComplianceLog(auth.siteId, from, to);
    let appended = 0;
    let failed = 0;
    for (const r of rows) {
      try {
        await appendInventoryRow(
          sheets,
          spreadsheetId,
          "Received",
          INVENTORY_SHEET_HEADERS.Received,
          complianceRowToSheetValues(r),
        );
        appended++;
      } catch (err) {
        logError("[Inventory] sheet sync row failed", err, { scope: "inventory.sheets" });
        failed++;
      }
    }
    json(res, 200, { appended, failed, total: rows.length });
    return true;
  }

  return false;
}

// ─── Sheets helpers ──────────────────────────────────────────

function complianceRowToSheetValues(r: ComplianceLogRow): string[] {
  // Order matches INVENTORY_RECEIVED_HEADERS in google-sheets.ts.
  // - `r.date` is YYYY-MM-DD; reformat to dd-MMM-yyyy so Sheets renders
  //   it as a date instead of the serial-number (the "46176" bug).
  // - scanned_at is stored UTC in the DB; we display IST everywhere.
  const s = (v: unknown) => (v === null || v === undefined ? "" : String(v));
  // Prefer scanned_at (UTC timestamp) over r.date (postgres to_char in
  // server TZ) so the IST shift is correct for both date and time.
  const source = r.scanned_at ?? r.date;
  return [
    source ? formatShortDateInIST(source) : "",
    r.scanned_at ? formatTimeInIST(r.scanned_at) : "",
    s(r.bill_number),
    s(r.vendor),
    s(r.product_name),
    s(r.product_name),
    s(r.hsn_code),
    s(r.unit),
    s(r.pack_size),
    s(r.expected_qty),
    s(r.qty_received),
    s(r.expiry_date),
    s(r.received_by),
    s(r.status),
  ];
}

