export async function setStockOnHand(input: {
  siteId: string;
  barcode: string;
  onHand: number;
  /** When provided (including explicit null), overwrites
   *  inventory_stock.nearest_expiry. Null clears the column ("no expiry"
   *  per the guard). Undefined leaves the column untouched. */
  nearestExpiry?: string | null;
  fallbackName?: string;
  fallbackCategory?: string | null;
  fallbackUnit?: string | null;
}): Promise<void> {
  const db = await getDb();
  const touchExpiry = input.nearestExpiry !== undefined;
  await db.execute({
    sql: `
      INSERT INTO inventory_stock (barcode, site_id, name, category, unit, on_hand, threshold, nearest_expiry)
      VALUES (?, ?, ?, ?, ?, GREATEST(?, 0), 0, ?)
      ON CONFLICT (site_id, barcode) DO UPDATE SET
        on_hand = GREATEST(?, 0),
        nearest_expiry = ${touchExpiry ? '?' : 'inventory_stock.nearest_expiry'},
        updated_at = now()
    `,
    args: touchExpiry
      ? [
          input.barcode,
          input.siteId,
          input.fallbackName ?? "Unknown",
          input.fallbackCategory ?? null,
          input.fallbackUnit ?? null,
          input.onHand,
          input.nearestExpiry,
          input.onHand,
          input.nearestExpiry,
        ]
      : [
          input.barcode,
          input.siteId,
          input.fallbackName ?? "Unknown",
          input.fallbackCategory ?? null,
          input.fallbackUnit ?? null,
          input.onHand,
