if (pathname === "/api/inventory/receipts" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);

  const id = asString(body.id);
  const barcode = asString(body.barcode);
  const qty = asNumber(body.qty);
  if (!id || !barcode || qty === null) {
    const missing: string[] = [];
    if (!id) missing.push("id");
    if (!barcode) missing.push("barcode");
    if (qty === null) missing.push("qty (numeric)");
    badRequest(res, `Cannot record receipt — missing or invalid: ${missing.join(", ")}`);
    return true;
  }

  const productName = asString(body.product_name) ?? "Unknown";
  const orderId = asString(body.order_id);
  let orderItemId = asString(body.order_item_id);
  const productId = asString(body.product_id);
  const expiryDate = asString(body.expiry_date);
  const flagged = asBool(body.flagged);
  const scannedAt = isoOrNow(body.scanned_at);

  // Fallback: if the client couldn't resolve an order_item_id but did
  // tell us which canonical product this is, look it up server-side
  // so the Received counter actually increments. Without this, the
  // counter stays at 0 whenever the field-app's local order cache
  // hasn't caught up to the latest validated bill.
  if (!orderItemId && productId) {
    const openItem = await findOpenItemByProductId(auth.siteId, productId);
    if (openItem) orderItemId = openItem.id;
  }

  const result = await insertReceipt({
    id,
    siteId: auth.siteId,
    orderId,
    orderItemId,
    productId,
    barcode,
    productName,
    qty,
    expiryDate,
    flagged,
    deviceId: auth.deviceId,
    guardId: auth.guardId,
    scannedAt,
  });

  // Only mutate downstream state on the first successful insert.
  // Retries land here too (id is idempotent) but must be no-ops.
  if (result.inserted) {
    if (orderItemId) {
      await addReceivedQty(orderItemId, qty);
    }
    const existing = await findProduct(auth.siteId, barcode);
    await adjustOnHand({
      siteId: auth.siteId,
      barcode,
      delta: qty,
      fallbackName: productName,
      fallbackCategory: existing?.category ?? null,
      fallbackUnit: existing?.unit ?? null,
    });
    // Defense in depth: persist the barcode → canonical_product mapping
    // server-side too, in case the field-app's explicit learn-barcode
    // outbox row was dropped. Skip synthetic "catalog_*" barcodes used
    // when no physical barcode exists.
    if (productId && !barcode.startsWith("catalog_")) {
      await learnBarcode({
        siteId: auth.siteId,
        barcode,
        productId,
        learnedFrom: "scan",
      }).catch(() => {});
      // Catalog tab on the linked Sheet needs to reflect the freshly-
      // learned barcode in its Barcode column. Debounced — many
      // receipts in a row coalesce into one push.
      void syncCatalogTabToSheet(auth.siteId).catch(() => {});
    }
  }

  // Fire-and-forget: push this receipt as a new row in the linked Google
  // Sheet (tab "Received"). Non-blocking so a Sheets outage never blocks
  // the field-app's outbox.
  if (result.inserted) {
    void appendComplianceRow(auth.siteId, id).catch((err) => {
      logError("[Inventory] Sheet append failed", err, { scope: "inventory.sheets" });
    });
    // Stock changed (on_hand +qty, maybe a new expiry to surface).
    // Debounced — bursts of receipts coalesce into one Sheets write.
    void syncStockTabToSheet(auth.siteId).catch(() => {});
  }

  json(res, 200, { id, inserted: result.inserted });
  return true;
}

if (pathname === "/api/inventory/products" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const barcode = asString(body.barcode);
  const name = asString(body.name);
  if (!barcode || !name) {
    const missing: string[] = [];
    if (!barcode) missing.push("barcode");
    if (!name) missing.push("name");
    badRequest(res, `Cannot register product — missing: ${missing.join(", ")}`);
    return true;
  }

  const packSize = asNumber(body.packSize ?? body.pack_size);
  await upsertProduct({
    siteId: auth.siteId,
    barcode,
    name,
    category: asString(body.category),
    unit: asString(body.unit),
    packSize: packSize !== null && packSize > 0 ? packSize : null,
    registeredBy: auth.guardName,
  });

  // Also promote the field-registered product into the canonical
  // catalog so it shows up in the dashboard's Catalog tab + the
  // linked Google Sheet, and learn the barcode → product mapping.
  // Otherwise field-only entries are invisible to admins.
  let canonicalProductId: string | null = null;
  let promotionError: string | null = null;
  try {
    const existing = await findCanonicalProductByName(auth.siteId, name);
    canonicalProductId = existing?.product_id ?? `prod_${Date.now().toString(36)}`;
    await upsertCanonicalProduct({
      productId: canonicalProductId,
      siteId: auth.siteId,
      canonicalName: name,
      category: asString(body.category),
      hsnCode: null,
      unit: asString(body.unit) ?? "pcs",
      packSize: packSize !== null && packSize > 0 ? packSize : 1,
      createdBy: `field:${auth.guardName}`,
    });
    await learnBarcode({
      siteId: auth.siteId,
      barcode,
      productId: canonicalProductId,
      learnedFrom: "field_registration",
    });
    // eslint-disable-next-line no-console
    console.log(
      `[Inventory] promoted field registration → canonical (site=${auth.siteId}, product_id=${canonicalProductId}, name=${name})`,
    );
    void syncCatalogTabToSheet(auth.siteId).catch((err) => {
      // eslint-disable-next-line no-console
      console.warn("[Inventory] Catalog sheet sync after promote failed:", err);
    });
  } catch (err) {
    promotionError = err instanceof Error ? err.message : String(err);
    logError("[Inventory] field-registration → canonical promote failed", err, {
      scope: "inventory.canonical",
    });
  }

  // Seed a zero-quantity stock row so the new SKU appears on the
  // Stock screen immediately, even before any receipts arrive.
  await upsertStock({
    siteId: auth.siteId,
    barcode,
    name,
    category: asString(body.category),
    unit: asString(body.unit),
  });

  json(res, 200, {
    barcode,
    registered: true,
    canonicalProductId,
    promotionError,
  });
  return true;
}

