// ─── Stock Lots (per-expiry batches) ──────────────────────────────

export type StockLot = {
  id: string;
  site_id: string;
  barcode: string;
  /** ISO YYYY-MM-DD; null means "no expiry". */
  expiry_date: string | null;
  qty: number;
  source: string | null;
  created_at: string;
  updated_at: string;
};

/** Compact lot shape for API responses + FEFO planning. */
export type LotSummary = {
  expiry_date: string | null;
  qty: number;
};

/** List remaining lots for a barcode, FEFO-ordered (earliest first,
 *  null-expiry last). Used by the field-app's dispense picker and the
 *  JIT stock fetch. */
export async function listLots(
  siteId: string,
  barcode: string,
): Promise<LotSummary[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT to_char(expiry_date, 'YYYY-MM-DD') AS expiry_date, qty
      FROM inventory_stock_lots
      WHERE site_id = ? AND barcode = ? AND qty > 0
      ORDER BY expiry_date NULLS LAST
    `,
    args: [siteId, barcode],
  });
  return result.rows.map((r) => ({
    expiry_date: (r as { expiry_date: string | null }).expiry_date,
    qty: Number((r as { qty: number | string }).qty),
  }));
}

/** Recompute the denormalised cache columns (on_hand, nearest_expiry)
 *  on inventory_stock from the current lot rows. Call after any lot
 *  mutation. Cheap — one indexed scan + one update. */
async function refreshStockCache(siteId: string, barcode: string): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      UPDATE inventory_stock SET
        on_hand = COALESCE((
          SELECT SUM(qty) FROM inventory_stock_lots
          WHERE site_id = ? AND barcode = ? AND qty > 0
        ), 0),
        nearest_expiry = (
          SELECT MIN(expiry_date) FROM inventory_stock_lots
          WHERE site_id = ? AND barcode = ? AND qty > 0 AND expiry_date IS NOT NULL
        ),
        updated_at = now()
      WHERE site_id = ? AND barcode = ?
    `,
    args: [siteId, barcode, siteId, barcode, siteId, barcode],
  });
}

/**
 * Add qty to the lot identified by (site, barcode, expiry). Inserts a
 * new lot row if none exists, otherwise increments the existing one.
 * Called by the receipts handler. Refreshes the cached on_hand /
 * nearest_expiry on inventory_stock for read-side consumers.
 */
export async function addLot(input: {
  siteId: string;
  barcode: string;
  expiryDate: string | null;
  qty: number;
  source?: string;
}): Promise<void> {
  if (input.qty <= 0) return;
  const db = await getDb();
  // We can't use ON CONFLICT with COALESCE expression keys reliably
  // across drivers, so do find-or-insert. Race window is tiny; the
  // unique index serialises any contention.
  const existing = await db.execute({
    sql: `
      SELECT id, qty FROM inventory_stock_lots
      WHERE site_id = ? AND barcode = ?
        AND COALESCE(expiry_date, DATE '0001-01-01') = COALESCE(?::DATE, DATE '0001-01-01')
      LIMIT 1
    `,
    args: [input.siteId, input.barcode, input.expiryDate],
  });
  const row = existing.rows[0] as { id: string; qty: number | string } | undefined;
  if (row) {
    await db.execute({
      sql: `UPDATE inventory_stock_lots SET qty = qty + ?, updated_at = now() WHERE id = ?`,
      args: [input.qty, row.id],
    });
  } else {
    await db.execute({
      sql: `
        INSERT INTO inventory_stock_lots (id, site_id, barcode, expiry_date, qty, source)
        VALUES (?, ?, ?, ?, ?, ?)
      `,
      args: [
        `lot_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`,
        input.siteId,
        input.barcode,
        input.expiryDate,
        input.qty,
        input.source ?? null,
      ],
    });
  }
  await refreshStockCache(input.siteId, input.barcode);
}

/**
 * Replace ALL lots for a (site, barcode) with the given list. Used by
 * the corrections endpoint when the guard re-stated the full per-batch
 * breakdown. Empty array clears all lots (zero stock). Empty/null
 * expiries collapse into a single "no-expiry" lot per the unique index.
 */
export async function replaceLots(input: {
  siteId: string;
  barcode: string;
  lots: LotSummary[];
  source?: string;
}): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `DELETE FROM inventory_stock_lots WHERE site_id = ? AND barcode = ?`,
    args: [input.siteId, input.barcode],
  });
  // Coalesce duplicates the caller may have sent (two batches with the
  // same expiry → one merged lot).
  const merged = new Map<string, number>();
  for (const lot of input.lots) {
    if (lot.qty <= 0) continue;
    const key = lot.expiry_date ?? "__none__";
    merged.set(key, (merged.get(key) ?? 0) + lot.qty);
  }
  for (const [key, qty] of merged) {
    const expiry = key === "__none__" ? null : key;
    await db.execute({
      sql: `
        INSERT INTO inventory_stock_lots (id, site_id, barcode, expiry_date, qty, source)
        VALUES (?, ?, ?, ?, ?, ?)
      `,
      args: [
        `lot_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`,
        input.siteId,
        input.barcode,
        expiry,
        qty,
        input.source ?? "correction",
      ],
    });
  }
  await refreshStockCache(input.siteId, input.barcode);
}

/**
 * Subtract qty from lots. When `picks` is provided, decrement those
 * specific (expiry, qty) pairs — the guard explicitly told us which
 * batches they pulled from. When absent, decrement FEFO (oldest expiry
 * first, null expiry last) — the "soft nudge" default.
 *
 * Returns the actual breakdown applied so the caller can persist it
 * (audit) and the field-app can update the local mirror.
 *
 * If the total in lots is short of qty, decrements what's there and
 * returns the partial breakdown. We do not let on_hand go negative.
 */
export async function decrementLots(input: {
  siteId: string;
  barcode: string;
  qty: number;
  picks?: LotSummary[] | null;
}): Promise<LotSummary[]> {
  if (input.qty <= 0) return [];
  const db = await getDb();
  const applied: LotSummary[] = [];

  // Path A — explicit picks
  if (input.picks && input.picks.length > 0) {
    for (const pick of input.picks) {
      if (pick.qty <= 0) continue;
      const row = await db.execute({
        sql: `
          SELECT id, qty FROM inventory_stock_lots
          WHERE site_id = ? AND barcode = ?
            AND COALESCE(expiry_date, DATE '0001-01-01') = COALESCE(?::DATE, DATE '0001-01-01')
            AND qty > 0
          LIMIT 1
        `,
        args: [input.siteId, input.barcode, pick.expiry_date],
      });
      const lot = row.rows[0] as { id: string; qty: number | string } | undefined;
      if (!lot) continue;
      const available = Number(lot.qty);
      const take = Math.min(available, pick.qty);
      if (take <= 0) continue;
      await db.execute({
        sql: `UPDATE inventory_stock_lots SET qty = qty - ?, updated_at = now() WHERE id = ?`,
        args: [take, lot.id],
      });
      applied.push({ expiry_date: pick.expiry_date, qty: take });
    }
  } else {
    // Path B — FEFO
    let remaining = input.qty;
    const lots = await db.execute({
      sql: `
        SELECT id, to_char(expiry_date, 'YYYY-MM-DD') AS expiry_date, qty
        FROM inventory_stock_lots
        WHERE site_id = ? AND barcode = ? AND qty > 0
        ORDER BY expiry_date NULLS LAST
      `,
      args: [input.siteId, input.barcode],
    });
    for (const r of lots.rows) {
      if (remaining <= 0) break;
      const lot = r as { id: string; expiry_date: string | null; qty: number | string };
      const available = Number(lot.qty);
      const take = Math.min(available, remaining);
      await db.execute({
        sql: `UPDATE inventory_stock_lots SET qty = qty - ?, updated_at = now() WHERE id = ?`,
        args: [take, lot.id],
      });
      applied.push({ expiry_date: lot.expiry_date, qty: take });
      remaining -= take;
    }
  }

  await refreshStockCache(input.siteId, input.barcode);
  // Vacuum empty lots so they don't clutter reads. Optional but cheap.
  await db.execute({
    sql: `DELETE FROM inventory_stock_lots WHERE site_id = ? AND barcode = ? AND qty <= 0`,
    args: [input.siteId, input.barcode],
  });
  return applied;
}

// ─── Canonical Products ──────────────────────────────────────────

