if (result.inserted) {
  await ensureStockRow({
    siteId: auth.siteId,
    barcode,
    fallbackName: productName,
  });

  // The field-app sends either:
  //   - lots: [{qty, expiry_date}]  (new batch model)
  //   - new_expiries: [DATE]         (legacy per-pack; one date per unit)
  //   - new_expiry: DATE             (legacy single)
  // Convert all three shapes to a unified replaceLots payload.
  const rawLots = Array.isArray(body.lots) ? body.lots : null;
  let lotsPayload: LotSummary[];
  if (rawLots) {
    lotsPayload = rawLots
      .map((l) => {
        const expiry = asString((l as Record<string, unknown>).expiry_date);
        const lotQty = asNumber((l as Record<string, unknown>).qty);
        if (lotQty === null || lotQty <= 0) return null;
        return { expiry_date: expiry, qty: lotQty } as LotSummary;
      })
      .filter((l): l is LotSummary => l !== null);
  } else if (newExpiries && newExpiries.length > 0) {
    // Legacy per-pack: collapse identical dates into a single lot.
    const merged = new Map<string, number>();
    for (const d of newExpiries) merged.set(d, (merged.get(d) ?? 0) + 1);
    lotsPayload = Array.from(merged.entries()).map(([d, q]) => ({
      expiry_date: d,
      qty: q,
    }));
  } else {
    lotsPayload = newQty > 0 ? [{ expiry_date: newExpiry ?? null, qty: newQty }] : [];
  }

  // Defensive: clamp to newQty so a malformed lots array (sums to
  // a different total) doesn't quietly disagree with the audit
  // row's new_qty.
  const total = lotsPayload.reduce((s, l) => s + l.qty, 0);
  if (total !== newQty && lotsPayload.length > 0 && total > 0) {
    const scale = newQty / total;
    lotsPayload = lotsPayload.map((l) => ({
      expiry_date: l.expiry_date,
      qty: Math.round(l.qty * scale),
    }));
  }
  await replaceLots({
    siteId: auth.siteId,
    barcode,
    lots: lotsPayload,
    source: "correction",
  });

