  //     mode this whole smoke test exists to detect)
  res.writeHead(200, {
    ...CORS_HEADERS,
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache, no-transform",
    "Connection": "keep-alive",
    "X-Accel-Buffering": "no",
  });

  // Helper — SSE wire format: `id: ...\nevent: ...\ndata: ...\n\n`.
  // Blank line terminates a message; EventSource then dispatches it.
  let eventId = 0;
  const send = (eventName: string, payload: Record<string, unknown>): void => {
    eventId += 1;
    const line =
      `id: ${eventId}\n` +
      `event: ${eventName}\n` +
      `data: ${JSON.stringify(payload)}\n\n`;
    try {
      res.write(line);
    } catch {
      // socket closed mid-write — let the close handler clean up
    }
  };

  // First event fires immediately so a successful connection is
  // visible to the client even if no heartbeats have fired yet.
  send("open", { ts: Date.now(), msg: "smoke stream opened" });

  // Heartbeat every 10 s. Two roles:
  //   1. Proves the stream is still receiving server-side writes.
  //   2. Keeps proxy idle-timeouts (nginx default 60 s) from killing
  //      the connection on quiet streams.
  const heartbeat = setInterval(() => {
    send("tick", { ts: Date.now(), eventId });
  }, 10_000);

  // Hard cap so a forgotten browser tab doesn't pin a worker forever.
  // 5 min is long enough to confirm proxy behavior is stable across
  // typical Bifrost idle-timeout windows.
  const maxDurationMs = 5 * 60 * 1000;
  const timeout = setTimeout(() => {
    send("close", { ts: Date.now(), reason: "max-duration" });
    try { res.end(); } catch { /* ignore */ }
  }, maxDurationMs);

  // Client disconnect cleanup. `req.on('close')` fires when the
  // browser/curl drops or the proxy times out. Without this, the
  // interval keeps firing into a dead socket forever.
  const cleanup = () => {
    clearInterval(heartbeat);
    clearTimeout(timeout);
  };
  req.on("close", cleanup);
  res.on("close", cleanup);

  return true;
}

