if (pathname.startsWith("/api/inventory/stock/") && method === "GET") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const barcode = decodeURIComponent(pathname.replace("/api/inventory/stock/", ""));
  if (!barcode) {
    badRequest(res, "barcode is required in the URL path (/api/inventory/stock/:barcode)");
    return true;
  }
  const row = await findStockJit(auth.siteId, barcode);
  if (!row) {
    json(res, 404, { error: `No stock row for barcode "${barcode}" on this site` });
    return true;
  }
  json(res, 200, { stock: row });
  return true;
}

if (pathname === "/api/inventory/products/normalize" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const rawName = asString(body.rawName) ?? asString(body.raw_name);
  if (!rawName) {
    badRequest(res, "rawName (or raw_name) is required to normalize a product name");
    return true;
  }
  try {
    const result = await normalizeProductName({
      siteId: auth.siteId,
      rawName,
    });
    json(res, 200, result);
  } catch (err) {
    logError("[Inventory] normalizeProductName failed", err, { scope: "inventory.normalize" });
    json(res, 500, {
      error: `Could not normalize "${rawName}": ${describeError(err)}`,
    });
  }
  return true;
}

