export type InventoryStockListRow = InventoryStockRow & {
  nearest_expiry: string | null;
  lots: LotSummary[];
};

export async function listStock(siteId: string): Promise<InventoryStockListRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_SELECT},
        to_char(s.nearest_expiry, 'YYYY-MM-DD') AS nearest_expiry,
        COALESCE(
          (SELECT json_agg(json_build_object(
                    'expiry_date', to_char(l.expiry_date, 'YYYY-MM-DD'),
                    'qty', l.qty)
                  ORDER BY l.expiry_date NULLS LAST)
             FROM inventory_stock_lots l
            WHERE l.site_id = s.site_id AND l.barcode = s.barcode AND l.qty > 0),
          '[]'::json
        ) AS lots
      ${STOCK_JOINS}
      WHERE s.site_id = ?
      ORDER BY s.name
    `,
    args: [siteId],
  });
  return result.rows.map((r) => {
    const row = r as Record<string, unknown>;
    // Some Postgres drivers (pg / pglite) return json columns as strings;
    // others auto-parse. Normalise.
    let lots = row.lots as LotSummary[] | string | null;
    if (typeof lots === "string") {
      try { lots = JSON.parse(lots) as LotSummary[]; } catch { lots = []; }
    }
    if (!Array.isArray(lots)) lots = [];
    return {
      ...(row as InventoryStockRow),
      nearest_expiry: (row.nearest_expiry as string | null) ?? null,
      lots: lots.map((l) => ({
        expiry_date: l.expiry_date ?? null,
        qty: Number(l.qty),
      })),
    } as InventoryStockListRow;
  });
}

